#!/usr/bin/env bash
# This file was generated by Anthropic, Claude Opus 5.5, "Go through doc/wiki-images and
# show the final versions on the wiki pages in doc/wiki without linking each one", 2026-10-27
# Usage: bash scripts/update-wiki-images.sh

cd "$(git rev-parse --show-toplevel)"

REPO=$(git remote get-url origin | sed -E 's#^git@github.com:#https://github.com/#; s#\.git$##')
BRANCH=$(git branch --show-current)

# Convert the top-level UML .puml diagrams into pictures in a separate folder
# (skips style.puml and the class pieces in UML subfolders, which are only included)
OUT="$(pwd)/doc/wiki-images/generated-uml-pngs"
if command -v plantuml >/dev/null; then
  rm -rf "$OUT"
  mkdir -p "$OUT"
  find doc/wiki-images/UML -maxdepth 1 -name "*.puml" ! -name "style.puml" -exec plantuml -tpng -o "$OUT" {} +
else
  echo "PlantUML not installed, skipping .puml conversion (run: brew install plantuml)"
fi

# Replace the text between <!-- NAME:start --> and <!-- NAME:end --> in a file
replace_section() {
  file="$1"; name="$2"; content="$3"
  grep -q "<!-- $name:start -->" "$file" || printf '\n<!-- %s:start -->\n<!-- %s:end -->\n' "$name" "$name" >> "$file"
  awk -v tmp="$content" -v s="<!-- $name:start -->" -v e="<!-- $name:end -->" '
    index($0, s) { print; while ((getline line < tmp) > 0) print line; skip=1; next }
    index($0, e) { skip=0 }
    !skip { print }
  ' "$file" > "$file.new" && mv "$file.new" "$file"
}

# List the files directly inside one folder (not its subfolders)
emit_files() {
  find "$1" -maxdepth 1 -type f | sort | while read -r f; do
    path=$(echo "$f" | sed 's/ /%20/g')
    name=$(basename "$f")
    case "$(echo "$name" | tr 'A-Z' 'a-z')" in
      style.puml) ;;
      *.png|*.jpg|*.jpeg|*.gif|*.svg|*.webp) echo; echo "![$name]($REPO/raw/$BRANCH/$path)" ;;
      *.pdf|*.puml) echo; echo "- [$name]($REPO/blob/$BRANCH/$path)" ;;
    esac
  done
}

# Loose files first, then each subfolder under its own heading.
# A folder written as "top:NAME" shows only its loose files.
gallery() {
  folder="$1"; top=0
  case "$folder" in top:*) top=1; folder="${folder#top:}" ;; esac
  dir="doc/wiki-images/$folder"
  [ -d "$dir" ] || return
  emit_files "$dir"
  [ "$top" = 1 ] && return
  find "$dir" -mindepth 1 -type d | sort | while read -r sub; do
    echo; echo "### ${sub#$dir/}"
    emit_files "$sub"
  done
}

update_page() {
  page="doc/wiki/$1"; shift
  tmp=$(mktemp)
  for folder in "$@"; do gallery "$folder"; done > "$tmp"
  replace_section "$page" images "$tmp"
  rm -f "$tmp"
}

# List meeting notes in the sidebar, linking to doc/meeting-notes in the repo (no copies)
update_meetings() {
  src="doc/meeting-notes"
  [ -d "$src" ] || return
  tmp=$(mktemp)
  find "$src" -type f -name "*.md" | sort -r | while read -r f; do
    path=$(echo "$f" | sed 's/ /%20/g; s/,/%2C/g')
    echo "* [$(basename "$f" .md)]($REPO/blob/$BRANCH/$path)"
  done > "$tmp"
  replace_section doc/wiki/_Sidebar.md meetings "$tmp"
  rm -f "$tmp"
}

# Which folders go on which page
update_page CRC.md   "CRC-Cards/final version"
update_page Figma.md "Figma"
update_page UML.md   "top:generated-uml-pngs"

update_meetings

echo "Wiki pages updated."
